public class Room {
    private String name;
    private double length;
    private double width;

    // No-argument constructor: sets sensible starting values
    public Room() {
        this.name = "Unnamed";
        this.length = 0.0;
        this.width = 0.0;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public double getLength() {
        return length;
    }

    public void setLength(double length) {
        this.length = length;
    }

    public double getWidth() {
        return width;
    }

    public void setWidth(double width) {
        this.width = width;
    }

    public double area() {
        return length * width;
    }

    @Override
    public String toString() {
        return "Room[name=" + name + ", length=" + length
                + ", width=" + width + ", area=" + area() + "]";
    }
}
